// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.streamimport com.roshan.persona.common.CorrelationIdimport kotlinx.coroutines.CancellationExceptionimport kotlinx.coroutines.Jobimport kotlinx.coroutines.channels.BufferOverflowimport kotlinx.coroutines.flow.Flowimport kotlinx.coroutines.flow.MutableSharedFlowimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.SharedFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asSharedFlowimport kotlinx.coroutines.flow.asStateFlowimport timber.log.Timberimport java.util.concurrent.ConcurrentHashMapimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Stream Coordinator. * * Manages real-time token streaming from LLM layers (L3/L4) to UI and TTS. * Per-request channels ensure concurrent requests don't interfere. * * ## Architecture * * ``` * Layer 3/4 generates token *         ↓ * StreamCoordinator.emitToken(correlationId, token) *         ↓ * ┌───────────────┬─────────────────┐ * │  UI Flow      │  TTS Callback   │ * │  (SharedFlow) │  (suspend fn)   │ * └───────────────┴─────────────────┘ *         ↓                 ↓ *   UI shows token     TTS speaks token * ``` * * ## Per-Request Isolation * * Each request gets its own [SharedFlow] (created lazily on first emit). * UI collects its own request's flow — concurrent requests don't mix. * * ## Barge-In (User Interruption) * * When user starts speaking (or taps "stop"), [cancel] is called: *   1. Active LLM generation is cancelled (via [CancellationToken]) *   2. TTS stops speaking *   3. Partial response is preserved (whatever was streamed so far) *   4. UI shows "[interrupted]" indicator * * ## TTS Bridge * * TTS receives tokens via a callback (not Flow) because TTS engines typically * use callback APIs. The coordinator calls [TtsBridge.speak] for each token. * * @see <a href="docs/spec/module2-spec-review.pdf">§10.2 StreamCoordinator</a> */@Singletonclass StreamCoordinator @Inject constructor(    private val ttsBridge: TtsBridge?,) {    // Per-request SharedFlow (lazily created)    private val flowsByCorrelationId = ConcurrentHashMap<CorrelationId, MutableSharedFlow<String>>()    // Per-request cancellation tokens    private val cancellationTokensByCorrelationId = ConcurrentHashMap<CorrelationId, CancellationToken>()    // Currently active request (for barge-in — only one active at a time per UI)    private val _activeCorrelationId = MutableStateFlow<CorrelationId?>(null)    val activeCorrelationId: StateFlow<CorrelationId?> = _activeCorrelationId.asStateFlow()    /**     * Get the token stream for [correlationId] (for UI to collect).     *     * Creates a new flow if one doesn't exist yet. UI should call this BEFORE     * the brain starts processing, so it doesn't miss early tokens.     *     * @param correlationId the request to listen to     * @return SharedFlow of tokens (replay=0, buffer=64, drop-oldest)     */    fun getTokenStream(correlationId: CorrelationId): SharedFlow<String> {        return flowsByCorrelationId.computeIfAbsent(correlationId) {            MutableSharedFlow(                replay = 0,                extraBufferCapacity = DEFAULT_BUFFER_CAPACITY,                onBufferOverflow = BufferOverflow.DROP_OLDEST,            )        }.asSharedFlow()    }    /**     * Emit a token to the stream (called by L3/L4 during generation).     *     * @param correlationId which request this token belongs to     * @param token the generated token (may be partial word, space, punctuation)     * @return true if emitted, false if request was cancelled     */    suspend fun emitToken(correlationId: CorrelationId, token: String): Boolean {        // Check cancellation        val cancellationToken = cancellationTokensByCorrelationId[correlationId]        if (cancellationToken?.isCancelled == true) {            Timber.tag("NOUS.Stream").v("Token emit skipped (cancelled): %s", correlationId.value.take(8))            return false        }        // Mark as active        _activeCorrelationId.value = correlationId        // Emit to flow        val flow = flowsByCorrelationId.computeIfAbsent(correlationId) {            MutableSharedFlow(                replay = 0,                extraBufferCapacity = DEFAULT_BUFFER_CAPACITY,                onBufferOverflow = BufferOverflow.DROP_OLDEST,            )        }        flow.emit(token)        // Bridge to TTS        if (ttsBridge != null) {            try {                ttsBridge.speak(token)            } catch (e: Exception) {                Timber.tag("NOUS.Stream").w(e, "TTS bridge failed (non-fatal)")            }        }        return true    }    /**     * Non-suspend variant of [emitToken] — uses [MutableSharedFlow.tryEmit] so     * it can be called from a non-suspend lambda (e.g. OkHttp streaming     * callback, JNI LLM token callback, or a synchronous `onToken` lambda).     *     * Returns `true` if the token was emitted to the SharedFlow, `false` if:     *   - the request was cancelled, OR     *   - the SharedFlow buffer was full (DROP_OLDEST policy applied), OR     *   - the TTS bridge could not be invoked synchronously.     *     * Note: TTS bridging is skipped in this synchronous path. TTS is driven     * by the regular [emitToken] suspend flow when the brain pipeline runs     * in a coroutine context. Use this method only when the caller is NOT     * in a coroutine context.     */    fun emitTokenSync(correlationId: CorrelationId, token: String): Boolean {        // Check cancellation        val cancellationToken = cancellationTokensByCorrelationId[correlationId]        if (cancellationToken?.isCancelled == true) {            Timber.tag("NOUS.Stream").v("Token emit skipped (cancelled): %s", correlationId.value.take(8))            return false        }        // Mark as active        _activeCorrelationId.value = correlationId        // Emit to flow — tryEmit returns false if buffer overflow occurred.        val flow = flowsByCorrelationId.computeIfAbsent(correlationId) {            MutableSharedFlow(                replay = 0,                extraBufferCapacity = DEFAULT_BUFFER_CAPACITY,                onBufferOverflow = BufferOverflow.DROP_OLDEST,            )        }        return flow.tryEmit(token)    }    /**     * Emit a complete message (for non-streaming layers like L1/L2).     *     * Used when the response is instant (rule fire, skill execute) and there's     * no token-by-token streaming. The full message is emitted as a single "token".     */    suspend fun emitComplete(correlationId: CorrelationId, message: String): Boolean {        return emitToken(correlationId, message)    }    /**     * Mark a request as complete.     *     * Called by the orchestrator after the final response is ready. Cleans up     * the flow (but allows late collectors to receive the last few buffered     * tokens before the flow is removed).     *     * @param correlationId the completed request     */    fun complete(correlationId: CorrelationId) {        Timber.tag("NOUS.Stream").v("Stream complete: %s", correlationId.value.take(8))        cancellationTokensByCorrelationId.remove(correlationId)        // Don't remove the flow immediately — late collectors might be reading        // It'll be cleaned up by cleanupOldFlows() or the next request        if (_activeCorrelationId.value == correlationId) {            _activeCorrelationId.value = null        }    }    /**     * Cancel a request (barge-in).     *     * Called when user starts speaking or taps "stop". Marks the cancellation     * token so further [emitToken] calls return false. The orchestrator's     * suspend function will throw [CancellationException] on next suspension point.     *     * @param correlationId the request to cancel     * @param reason why it was cancelled (for audit log)     */    fun cancel(correlationId: CorrelationId, reason: String = "User cancelled") {        Timber.tag("NOUS.Stream").i("Stream cancelled (%s): %s", reason, correlationId.value.take(8))        val token = cancellationTokensByCorrelationId.computeIfAbsent(correlationId) { CancellationToken() }        token.cancel(reason)        if (_activeCorrelationId.value == correlationId) {            _activeCorrelationId.value = null        }        // Stop TTS        if (ttsBridge != null) {            try {                ttsBridge.stop()            } catch (e: Exception) {                Timber.tag("NOUS.Stream").w(e, "TTS stop failed (non-fatal)")            }        }    }    /**     * Get the cancellation token for [correlationId] (for the orchestrator to     * check between steps).     */    fun getCancellationToken(correlationId: CorrelationId): CancellationToken {        return cancellationTokensByCorrelationId.computeIfAbsent(correlationId) { CancellationToken() }    }    /**     * Cancel all active streams (e.g., when app goes to background).     */    fun cancelAll(reason: String = "App backgrounded") {        // Collect all correlation IDs from both maps (tokens may not exist for flows yet)        val allIds = (cancellationTokensByCorrelationId.keys + flowsByCorrelationId.keys).toSet()        for (correlationId in allIds) {            cancel(correlationId, reason)        }    }    /**     * Clean up flows older than [maxAgeMs] (called periodically by WorkManager).     */    fun cleanupOldFlows(maxAgeMs: Long = CLEANUP_AGE_MS) {        // In a real impl, we'd track creation time per flow.        // For now, just clear all non-active flows.        val active = _activeCorrelationId.value        val toRemove = flowsByCorrelationId.keys.filter { it != active }        for (correlationId in toRemove) {            flowsByCorrelationId.remove(correlationId)        }        if (toRemove.isNotEmpty()) {            Timber.tag("NOUS.Stream").v("Cleaned up %d old flows", toRemove.size)        }    }    /**     * Number of active streams (for metrics).     */    fun activeStreamCount(): Int = flowsByCorrelationId.size    companion object {        const val DEFAULT_BUFFER_CAPACITY = 64        const val CLEANUP_AGE_MS = 60_000L  // 1 minute    }}/** * Cancellation token for barge-in support. * * Polled by the orchestrator between steps (especially in L5 agentic loops). * When cancelled, [throwIfCancelled] throws [CancellationException]. */class CancellationToken {    @Volatile    private var cancelled: Boolean = false    @Volatile    private var reason: String? = null    /** Whether this token has been cancelled. */    val isCancelled: Boolean get() = cancelled    /** Why it was cancelled (null if not cancelled). */    val cancellationReason: String? get() = reason    /** Mark as cancelled. */    fun cancel(reason: String) {        cancelled = true        this.reason = reason    }    /**     * Throw [CancellationException] if cancelled.     *     * Called by the orchestrator between steps.     */    fun throwIfCancelled() {        if (cancelled) {            throw CancellationException(reason ?: "Cancelled")        }    }}/** * TTS bridge — receives tokens for text-to-speech. * * Real implementation: :feature:voice's [com.roshan.persona.voice.di.VoiceTtsBridge] * (bound via VoiceModule's Hilt graph) — wraps `EmotionalTtsEngine` and * buffers tokens until sentence boundaries before speaking. * * Test fakes: `NoOpTtsBridge` + `FakeTtsBridge` in * `src/test/kotlin/.../stream/TestTtsBridges.kt`. */interface TtsBridge {    /**     * Speak a token (called for each streamed token).     *     * The TTS engine should buffer tokens internally and speak them in order.     * Emoji and special characters should be stripped before speaking.     */    suspend fun speak(token: String)    /**     * Stop speaking immediately (barge-in).     */    fun stop()}
